<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {api,mutation} from '../api/client'
import type {StudyTrack,StudyPlan,StudyModule} from '../types/study'
import type {LearningEvidence} from '../types/practice'
import {learningStates} from '../types/practice'
import LearningEvidenceCard from './LearningEvidenceCard.vue'
type Attempt={attempt_id:string;available?:boolean;workspace_id:string;practice_id:string;ordinal:number;help_mode:string;exercise_version:number;instruction:string;binding:{ended_at:string|null};workspace_revision:number;learning_state:string;evidence:LearningEvidence}
const props=defineProps<{track:StudyTrack;plan:StudyPlan;module:StudyModule}>()
const emit=defineEmits<{open:[value:{workspace_id:string;practice_id:string}];delivery:[value:{workspace_id:string;practice_id:string}];changed:[]}>()
const rows=ref<Attempt[]>([]),creating=ref(false),busy=ref(false),mode=ref('agent_assisted'),kind=ref('practice'),instruction=ref(''),acceptance=ref(''),variation=ref(''),ack=ref(false)
const write=mutation(),leaf=computed(()=>!props.plan.modules.some(m=>m.parent_key===props.module.key))
const outcome=computed(()=>props.plan.module_outcomes?.[props.module.key])
let serial=0
async function load(){const n=++serial;try{const value=await api<Attempt[]>('/study/tracks/'+props.track.track_id+'/attempts?plan_id='+props.plan.id+'&module_key='+encodeURIComponent(props.module.key));if(n===serial)rows.value=value}catch(e){ElMessage.error(String(e))}}
watch(()=>[props.plan.id,props.module.key,props.track.revision],()=>{void load()},{immediate:true})
function prepare(){instruction.value=props.module.steps.join('\n')+'\n交付：'+props.module.deliverable;acceptance.value=props.module.acceptance.join('\n');ack.value=false;creating.value=true}
async function create(){busy.value=true;try{const value=await write<{workspace_id:string;practice_id:string}>('/study/tracks/'+props.track.track_id+'/attempts','POST',{expected_revision:props.track.revision,plan_id:props.plan.id,module_key:props.module.key,instruction:instruction.value,acceptance:acceptance.value.split('\n').map(s=>s.trim()).filter(Boolean),exercise_kind:kind.value,variation:variation.value,help_mode:mode.value,scope_acknowledged:ack.value});creating.value=false;emit('changed');emit('open',value);await load();ElMessage.success('新尝试已建立；没有调用模型或执行命令')}catch(e){ElMessage.error(String(e))}finally{busy.value=false}}
async function close(a:Attempt){try{const {value}=await ElMessageBox.prompt('结束此尝试的原因；已有材料和提交保留。','结束尝试',{inputValidator:s=>!!s.trim()||'请填写原因'});busy.value=true;await api('/study/tracks/'+props.track.track_id+'/attempts/'+a.attempt_id+'/close','POST',{expected_revision:a.workspace_revision,reason:value});await load();emit('changed')}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(String(e))}finally{busy.value=false}}
</script>
<template><section class="module-practice"><h3>练习与成果证据</h3><LearningEvidenceCard v-if="outcome" :evidence="outcome"/><p v-if="!leaf" class="muted">选择叶模块建立一项有明确产物的练习。</p><el-button v-else type="primary" plain :disabled="busy" @click="prepare">为本模块开始一次尝试</el-button><small>固定练习与验收条件，每次尝试单独记录；不自动调用 Agent。</small><details v-if="rows.length" open><summary>尝试记录 · {{rows.length}}</summary><article v-for="a in rows.slice(-10).reverse()" :key="a.attempt_id"><template v-if="a.available!==false"><strong>第 {{a.ordinal}} 次 · {{a.help_mode==='independent'?'独立模式':'Agent 辅助模式'}}</strong><p>{{learningStates[a.learning_state]??a.learning_state}}</p><small>练习 v{{a.exercise_version}} · {{a.binding.ended_at?'已冻结 / 结束':'进行中'}}</small><el-button size="small" @click="emit('open',a)">打开工作区</el-button><el-button size="small" @click="emit('delivery',a)">成果与人工验收</el-button><el-button v-if="!a.binding.ended_at" size="small" link :disabled="busy" @click="close(a)">结束本次尝试</el-button></template><p v-else>原依据不可用，保留尝试编号。</p></article></details></section>
<el-dialog v-model="creating" title="冻结练习并开始新尝试" width="min(650px,95vw)"><el-form label-position="top"><el-form-item label="练习内容"><el-input v-model="instruction" type="textarea" :rows="4" maxlength="4000"/></el-form-item><el-form-item label="验收条件（每行一项，最多6项）"><el-input v-model="acceptance" type="textarea" :rows="3"/></el-form-item><el-form-item label="任务类型"><el-select v-model="kind"><el-option label="模块练习" value="practice"/><el-option label="迁移练习" value="transfer"/></el-select></el-form-item><el-form-item v-if="kind==='transfer'" label="与参考实现不同的输入、接口或失败条件"><el-input v-model="variation" type="textarea" maxlength="2000"/></el-form-item><el-form-item label="本次帮助模式"><el-select v-model="mode"><el-option label="允许 Agent 辅助" value="agent_assisted"/><el-option label="本人独立尝试" value="independent"/></el-select></el-form-item><el-alert v-if="mode==='independent'" title="使用新的空白练习副本。提交或结束前，本账号的导师和 IDE Agent 暂停；此副本不能应用 Agent 补丁。固定参考代码可读，外部帮助仍须本人声明。" type="warning" :closable="false"/><p class="muted">成果需包含代码与运行记录、本人解释和迁移/差异说明，再逐项人工核对。命令仍需单独确认。</p><el-checkbox v-model="ack">我确认当前练习范围与验收条件，并同意记录上述帮助条件。</el-checkbox></el-form><template #footer><el-button @click="creating=false">取消</el-button><el-button type="primary" :loading="busy" :disabled="!ack||!instruction.trim()||!acceptance.trim()||(kind==='transfer'&&!variation.trim())" @click="create">建立本次尝试</el-button></template></el-dialog>
</template>
<style scoped>.module-practice{border-top:1px solid #d9e5dc;margin-top:14px;padding-top:8px}.module-practice p,.muted,small{font-size:12px;color:#6a7d70;line-height:1.7}small{display:block;margin:7px 0}.module-practice article{padding:12px 0;border-bottom:1px solid #e2eae4;font-size:12px}.module-practice .el-button{margin:4px 4px 4px 0;white-space:normal;height:auto;min-height:28px}summary{font-size:12px;cursor:pointer}</style>
